import React from 'react';

interface LogoProps {
  className?: string;
  width?: number;
  height?: number;
  alt?: string;
}

const Logo = ({ 
  className, 
  width = 24, 
  height = 24, 
  alt = "StackOne Logo" 
}: LogoProps) => {
  return (
    <img 
      src="data:image/png;base64,"
      alt={alt}
      width={width}
      height={height}
      className={className}
    />
  );
};

export default Logo;
